From a2fe17ced1c47fb21cf9dc7d35fafc2b829d2180 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 21:35:36 +0100
Subject: [PATCH] applets/taskmanager: let apps name their audio streams in
 .desktop files

Apps like MPD frontends don't play audio themselves, so their window
can't be matched to the stream and gets no volume controls. They can
now list the stream's app names in X-KDE-AudioStreamAppNames instead.

BUG: 511921
---
 applets/taskmanager/backend.cpp  | 13 +++++++++++++
 applets/taskmanager/backend.h    |  1 +
 applets/taskmanager/qml/Task.qml |  4 ++++
 3 files changed, 18 insertions(+)

diff --git a/applets/taskmanager/backend.cpp b/applets/taskmanager/backend.cpp
index 1005d2a981..75c3c5a369 100644
--- a/applets/taskmanager/backend.cpp
+++ b/applets/taskmanager/backend.cpp
@@ -146,6 +146,19 @@ QStringList Backend::applicationCategories(const QUrl &launcherUrl)
     return desktopFile.desktopGroup().readXdgListEntry(QStringLiteral("Categories"));
 }

+QStringList Backend::audioStreamAppNames(const QUrl &launcherUrl)
+{
+    const QUrl desktopEntryUrl = tryDecodeApplicationsUrl(launcherUrl);
+
+    if (!desktopEntryUrl.isValid() || !desktopEntryUrl.isLocalFile() || !KDesktopFile::isDesktopFile(desktopEntryUrl.toLocalFile())) {
+        return QStringList();
+    }
+
+    KDesktopFile desktopFile(desktopEntryUrl.toLocalFile());
+
+    return desktopFile.desktopGroup().readXdgListEntry(QStringLiteral("X-KDE-AudioStreamAppNames"));
+}
+
 QVariantList Backend::jumpListActions(const QUrl &launcherUrl, QObject *parent)
 {
     QVariantList actions;
